Let $d$ be a positive integer. Then the set of interpolated lc thresholds 
\begin{align*}
    \left \{
\operatorname{lct}(X;\mathcal{F})
\ \middle \vert \ 
\dim X=d, 
\text{ $X$ and $\mathcal{F}$ are $\mathbb Q$-Gorenstein, $\mathcal{F}$ is algebraically integrable} 
    \right \}
\end{align*}
satisfies the ACC.

Let $d$ be a positive integer. Then there exists an ACC set $\Gamma=\Gamma_{\operatorname{gilct}}\subset [0,1]$ depending only on $d$ with the following property. Assume that $(X,\mathcal{F},t)$ is a projective lc algebraically integrable adjoint foliated structure of dimension $d$ such that
    $$tK_{\mathcal{F}}+(1-t)K_X\equiv 0.$$
    Then either $t\in\Gamma$, or $K_X\equiv K_{\mathcal{F}}\equiv 0$.

Let $d$ be a positive integer. Then there exists a number $t=t(d)\in(0,1)$ depending only on $d$ with the following property.


    Assume that $f\colon X\to T$ is a stable family of maximal variation such that $X$ is normal and projective, and $\dim X=d$. Then:
    \begin{enumerate}
        \item $K_{t}:=tK_{X/T}+(1-t)K_X$ is big.
        \item Assume that $\operatorname{vol}(K_t)\leq C$ for some constant $C$. Then $X$ is birationally bounded.
    \end{enumerate}

Let $d$ be a positive integer and $\epsilon$ a positive real number. Then the set of projective varieties $X$ such that
\begin{enumerate}
    \item ${\mathfrak{A}}:=(X,\mathcal{F},t)$ is a Fano algebraically integrable adjoint foliated structure,
    \item $\dim X=d$,
    \item $\alpha({\mathfrak{A}})^d\cdot\operatorname{vol}(-K_{{\mathfrak{A}}})\geq\epsilon$, and
    \item $t\leq 1-\epsilon$
\end{enumerate}
forms a bounded family. 
Moreover, the set of $(X,\mathcal{F})$ such that (1-4) hold and
\begin{enumerate}
    \item[(5)] $t\geq\epsilon$
\end{enumerate}
forms a bounded family.

Let $d$ be a positive integer and $\Gamma\subset [0,1]$ a DCC set. Then the set of foliated pairs $(X,\mathcal{F})$ such that
\begin{enumerate}
    \item ${\mathfrak{A}}:=(X,\mathcal{F},t)$ is a Fano algebraically integrable adjoint foliated structure,
    \item $\dim X=d$ and $t\in\Gamma\backslash\{0\}$, and
    \item $\alpha({\mathfrak{A}})>1$
\end{enumerate}
forms a bounded family.
